(()=>{'use strict';
const $=id=>document.getElementById(id),esc=escapeHTML,amount=v=>v===null||v===undefined||v===''?'Keine Angabe':euro(v),date=v=>v?v.split('-').reverse().join('.'):'Keine Angabe';let editing=null;
function readArray(key){try{const x=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(x)?x:[]}catch{return []}}
function projectLinks(key){const list=[];for(const [storage,path,param,label]of [['immobrain-fix-flip-saved-v1','/fix-flip.html','calculation','Kalkulation'],['immobrain-viewings-v1','/besichtigung.html','viewing','Besichtigung'],['immobrain-renovation-plans-v1','/renovierung.html','plan','Renovierungsplan']]){const all=readArray(storage).filter(x=>(x.values?.listingRef||x.data?.fields?.listingRef||x.listingRef)===key);for(const x of all)list.push(`<a class="reset" href="${path}?${param}=${encodeURIComponent(x.id)}">${label}: ${esc(x.name||'Öffnen')} ↗</a>`)}list.push(`<a class="reset" href="/fix-flip.html">Neue Kalkulation (Objekt auswählen)</a>`,`<a class="reset" href="/besichtigung.html?listing=${encodeURIComponent(key)}">Zur Besichtigung</a>`,`<a class="reset" href="/renovierung.html">Renovierungsplaner öffnen</a>`);return list.join('')}
function summary(o){return `<dl class="owned-facts"><div><dt>Tatsächlicher Kaufpreis</dt><dd>${amount(o.purchasePrice)}</dd></div><div><dt>Kaufdatum</dt><dd>${date(o.purchaseDate)}</dd></div><div><dt>Übergabe</dt><dd>${date(o.handoverDate)}</dd></div><div><dt>Nutzung</dt><dd>${esc(OwnershipCore.usages[o.usage]||'Keine Angabe')}</dd></div><div><dt>Kaltmiete / Monat</dt><dd>${amount(o.rent)}</dd></div><div><dt>Hausgeld / Monat</dt><dd>${amount(o.hausgeld)}</dd></div><div><dt>Kreditrate / Monat</dt><dd>${amount(o.loanPayment)}</dd></div></dl>`}
function renderOwned(){const all=OwnershipCore.purchased(savedState),usage=$('owned-usage').value,visible=all.filter(([,v])=>!usage||v.ownership?.usage===usage);$('owned-count').textContent=all.length+' gekaufte Immobilie'+(all.length===1?'':'n');$('owned-list').innerHTML=visible.map(([key,v])=>{const o=v.ownership||{},x=v.snapshot;return `<section class="owned-property"><div class="owned-heading"><span class="owned-badge">✓ Gekauft</span><button type="button" class="btn" data-owned-edit="${esc(key)}">Objekt &amp; Verwaltung bearbeiten</button></div>${x?cardMarkup(x,true):`<h2>${esc(key)}</h2>`}${summary(o)}${o.managerName||o.managerPhone||o.managerEmail?`<p class="owned-contact"><strong>${esc(o.managerName||'Ansprechpartner')}</strong>${o.managerPhone?` · <a href="tel:${esc(o.managerPhone.replace(/[^+0-9*#]/g,''))}">${esc(o.managerPhone)}</a>`:''}${o.managerEmail?` · <a href="mailto:${esc(o.managerEmail)}">${esc(o.managerEmail)}</a>`:''}</p>`:''}${o.notes?`<p class="owned-notes">${esc(o.notes)}</p>`:''}<div class="owned-links">${projectLinks(key)}</div><p class="saved-note">Inseratpreis und tatsächlicher Kaufpreis werden getrennt gespeichert. Beträge werden nicht automatisch in bestehende Kalkulationen übertragen.</p></section>`}).join('')||'<p class="saved-empty">'+(all.length?'Keine Immobilie für diese Nutzung.':'Noch keine gekaufte Immobilie. Lege ein Objekt an oder ändere unter „Meine Objekte“ den Status auf „Gekauft“.')+'</p>'}
function open(key){const entry=savedState[key];if(!entry)return;editing=key;const form=$('owned-form');form.reset();const x=entry.snapshot||{},a=entry.address||x,o=entry.ownership||{};const defaults={title:x.title||'',street:a.street||'',zipcode:a.zipcode||'',city:a.city||'',area:x.square_meter??'',rooms:x.rooms??'',year:entry.year_override??String(x.year_of_construction||'').slice(0,4),energy:x.energy_efficency_class||'',heating:x.heating_type||'',...o};for(const [name,value]of Object.entries(defaults)){const f=form.elements.namedItem(name);if(f)f.value=value??''}$('owned-message').textContent='';$('owned-dialog').showModal();form.elements.namedItem('title').focus()}
window.renderOwned=renderOwned;window.openOwnedObject=open;
$('owned-add').onclick=()=>window.openOwnObject(null,{status:'gekauft'});$('owned-usage').onchange=renderOwned;$('owned-close').onclick=()=>$('owned-dialog').close();$('owned-list').addEventListener('click',e=>{const b=e.target.closest('[data-owned-edit]');if(b)open(b.dataset.ownedEdit);else handleCardClick(e)});
$('owned-form').onsubmit=e=>{e.preventDefault();const form=$('owned-form');if(!editing||!form.reportValidity())return;const previous=savedState[editing];if(!previous)return;const input=Object.fromEntries(new FormData(form));try{const next=OwnershipCore.update(previous,input);next.snapshot={...previous.snapshot,local_key:previous.snapshot?.local_key||editing,title:input.title.trim(),square_meter:input.area===''?null:Number(input.area),rooms:input.rooms===''?null:Number(input.rooms),year_of_construction:input.year||null,energy_efficency_class:input.energy||null,heating_type:input.heating.trim()||null};if(next.snapshot.square_meter>0){next.snapshot.price_per_square_meter=next.snapshot.price!=null?Number(next.snapshot.price)/next.snapshot.square_meter:null;next.snapshot.rent_per_square_meter=next.snapshot.rent_price!=null?Number(next.snapshot.rent_price)/next.snapshot.square_meter:null}else{next.snapshot.price_per_square_meter=null;next.snapshot.rent_per_square_meter=null}next.address={street:input.street.trim(),zipcode:input.zipcode.trim(),city:input.city.trim()};delete next.year_override;savedState[editing]=next;if(!saveState()){savedState[editing]=previous;$('owned-message').textContent='Speicherung fehlgeschlagen. Deine Eingaben bleiben geöffnet.';return}$('owned-dialog').close();renderOwned();renderObjects();render()}catch(err){$('owned-message').textContent=err.message}};
window.addEventListener('hashchange',()=>{if(location.hash==='#bestand')renderOwned()});window.addEventListener('storage',()=>{if(location.hash==='#bestand')renderOwned()});window.addEventListener('pageshow',()=>{if(location.hash==='#bestand')renderOwned()});if(location.hash==='#bestand')renderOwned();
})();
